function irouteSaveSync(data) {
  if (!data || !data.sync_metadata) return;
  var sm = data.sync_metadata;
  pm.collectionVariables.set('content_hash', sm.content_hash || '');
  pm.collectionVariables.set('workflow_version', sm.workflow_version || '');
  pm.environment.set('content_hash', sm.content_hash || '');
  pm.environment.set('workflow_version', sm.workflow_version || '');
}
function irouteSaveJobIds(data) {
  var job = data.job || {};
  var sid = job.job_id || data.shipment_id || '';
  if (sid) {
    pm.collectionVariables.set('shipment_id', sid);
    pm.collectionVariables.set('job_id', sid);
    pm.collectionVariables.set('job_type', job.job_type || 'shipment');
    pm.environment.set('shipment_id', sid);
    pm.environment.set('job_id', sid);
    pm.environment.set('job_type', job.job_type || 'shipment');
  }
  if (job.job_no) {
    pm.collectionVariables.set('shipment_no', job.job_no);
    pm.environment.set('shipment_no', job.job_no);
  }
}
function irouteSaveWorkflowState(data) {
  var wf = data.workflow || {};
  var allowed = wf.allowed_actions || [];
  var codes = allowed.map(function (a) { return String(a.action_code || '').toUpperCase(); });
  var a7 = codes.indexOf('A7') >= 0 ? 'true' : 'false';
  pm.collectionVariables.set('a7_allowed', a7);
  pm.environment.set('a7_allowed', a7);
  var hint = data.next_action_hint || {};
  var closed = hint.job_closed === true ? 'true' : 'false';
  pm.collectionVariables.set('job_closed', closed);
  pm.environment.set('job_closed', closed);
  var nextCode = String((wf.next_action || {}).action_code || hint.action_code || '').toUpperCase();
  pm.collectionVariables.set('next_action_code', nextCode);
  pm.environment.set('next_action_code', nextCode);
}
function irouteSaveCodAmount(data) {
  var job = data.job || {};
  var pod = data.pod_cod || {};
  var amt = job.cod_amount || job.amount_due || pod.cod_amount || pod.amount_due || '';
  if (amt) {
    pm.collectionVariables.set('mobile_cod_amount', String(amt));
    pm.environment.set('mobile_cod_amount', String(amt));
  }
}
function irouteAssertToken() {
  var t = pm.variables.get('access_token') || '';
  if (!t || String(t).indexOf('{{') >= 0) throw new Error('Run 01 Login first — access_token missing.');
}
function irouteAssertBaseUrl() {
  var base = pm.variables.get('base_url') || '';
  if (base.indexOf('/api/v1/mobile') < 0) throw new Error('base_url must include /api/v1/mobile — got: ' + base);
}
